var t=`0492-fatteh-hummus`;var n=`world-0492`;var a=`SY`;var r=`western-asia`;var s=4;var o=27;var l={en:`Fatteh Hummus`,ua:`Фатте з нутом`};var d={en:`A traditional dish from Syria, centered on pita bread, canned chickpeas, plain yogurt, tahini. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Сирія. Основні складники: піта, консервований нут, натуральний йогурт, тахіні. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Toast these ingredients over medium heat for about 6 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 6 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:6,i:[[`pita-bread`,4,`pcs`]]},{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`canned-chickpeas`,450,`g`],[`water`,220,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`plain-yogurt`,460,`g`],[`tahini`,95,`g`],[`lemon-juice`,45,`ml`],[`garlic`,3,`clove`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`unsalted-butter`,35,`g`],[`pine-nut`,75,`g`],[`parsley`,25,`g`]]}];var u={slug:t,id:n,country:`SY`,region:r,servings:4,minutes:27,title:l,text:d,steps:g};export{a as country,u as default,n as id,o as minutes,r as region,s as servings,t as slug,g as steps,d as text,l as title};